struct ValueElementsSerializer<'a> {
    data: &'a ValueElements,
    seq: usize,
    type_name: &'static str,
    b64_cache: Option<String>,
}

impl<'a> ValueElementsSerializer<'a> {
    fn new(data: &'a ValueElements) -> Self {
        let b64_cache = match data {
            ValueElements::PrimitiveBinary(value) => Some(base64::display::Base64Display::new(value, &base64::engine::general_purpose::STANDARD).to_string()),
            _ => None,
        };
        Self { data, seq: 0, type_name: data.as_str(), b64_cache }
    }
}

